(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12 + Math.sin((x+y)*0.008+t*0.15)*8;
  const w1y = Math.cos(y*0.02-t*0.22)*18 + Math.sin(x*0.016+t*0.28)*12 + Math.cos((x-y)*0.009-t*0.12)*8;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.025-t*0.4)*8 + Math.cos(sy*0.02+t*0.35)*6;
  const w2y = Math.cos(sy*0.022+t*0.38)*8 + Math.sin(sx*0.018-t*0.42)*6;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.075, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.09, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.055, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.11, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.065, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.08, 1.9, 0.7],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*55, 0.1, 2.1, 0.85],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*45, 0.07, 1.8, 1.05]
  ];
  let aS=0, iS=0, cS=0, mS=0;
  for (const [sX,sY,f,sp,wt] of src) {
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    const w1=Math.sin(d*f-t*sp), w2=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    const w3=Math.cos(d*f*1.3-t*sp*0.8+0.7), w4=Math.sin(d*f*0.5+t*sp*1.1+2.3);
    aS+=w1*wt; iS+=w2*wt; cS+=w3*wt; mS+=w4*wt;
  }
  const tw=src.reduce((a,s)=>a+s[4],0);
  const act=aS/tw, inh=iS/tw, cross=cS/tw, mod=mS/tw;
  const bg=(Math.sin(fx*0.035+fy*0.022+t*0.7)+Math.sin(fx*0.028-fy*0.038+t*1.0)+Math.cos(fx*0.02+fy*0.03-t*0.6))/3;
  const turb=(Math.sin((fx+fy)*0.11+t*2.2)*0.3+Math.sin((fx-fy)*0.09-t*1.8)*0.3+Math.sin(fx*0.07*t*0.4)*0.2+Math.cos(fy*0.065-t*0.5)*0.2);
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2), ang=Math.atan2(fy-cy,fx-cx);
  const sp1=Math.sin(dist*0.045-ang*3-t*1.4), sp2=Math.sin(dist*0.035+ang*4-t*1.1), sp3=Math.cos(dist*0.06-ang*2+t*0.9);
  const spiral=(sp1+sp2+sp3)/3*0.45;
  const harm=Math.sin(ang*5+t*0.8)*Math.sin(dist*0.03-t*0.5)*0.25;
  const cell1=Math.sin(fx*0.14)*Math.sin(fy*0.14), cell2=Math.sin((fx+fy)*0.09+t*0.7), cell3=Math.cos((fx*0.7-fy*1.3)*0.08-t*0.5);
  const cell=(Math.tanh((cell1+cell2*0.6+cell3*0.4)*1.8))*0.28;
  const rd1=act-inh*0.65+cross*0.3+mod*0.2;
  const rd2=act*inh*0.5-cross*mod*0.3;
  const rd3=Math.tanh((rd1+bg*0.25+spiral+harm)*2.0)+Math.tanh(rd2*3.0)*0.3;
  const reaction=Math.tanh(rd3*1.8);
  const micro=Math.sin(fx*0.3+t*3)*Math.sin(fy*0.3-t*2.5)*0.08*(1+reaction);
  const blend=reaction*0.65+cell*0.2+turb*0.08+micro*0.07;
  const v=blend*0.5+0.5;
  const shift=Math.sin(t*0.15)*0.08+Math.cos(t*0.22)*0.05;
  const pal=[
    [5,12,52],[12,35,85],[18,65,105],[25,110,120],[45,155,130],
    [120,185,110],[195,195,75],[220,165,55],[215,120,60],[185,75,55],
    [150,45,50],[100,25,45],[55,15,40],[20,10,48],[5,12,52]
  ];
  const adj=Math.max(0,Math.min(1,v+shift));
  const idx=adj*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const pulse=0.85+Math.sin(reaction*Math.PI*1.5)*0.15;
  const edge=Math.abs(reaction)>0.75?1.2:Math.abs(reaction)>0.5?1.08:1.0;
  const glow=Math.max(0,reaction-0.6)*0.5;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*pulse*edge+glow*60)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*pulse*edge+glow*40)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*pulse*edge+glow*80)|0)
  ];
}
